  KEY `stock_requests_dispatched_by_foreign` (`dispatched_by`),
  KEY `stock_requests_received_by_foreign` (`received_by`),
  KEY `stock_requests_status_priority_index` (`status`,`priority`),
  KEY `stock_requests_requesting_facility_id_status_index` (`requesting_facility_id`,`status`),
  KEY `stock_requests_central_store_id_status_index` (`central_store_id`,`status`),
  KEY `stock_requests_request_date_status_index` (`request_date`,`status`),
  KEY `stock_requests_requested_by_index` (`requested_by`),
  CONSTRAINT `stock_requests_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`),
  CONSTRAINT `stock_requests_central_store_id_foreign` FOREIGN KEY (`central_store_id`) REFERENCES `facilities` (`id`) ON DELETE CASCADE,
  CONSTRAINT `stock_requests_dispatched_by_foreign` FOREIGN KEY (`dispatched_by`) REFERENCES `users` (`id`),
  CONSTRAINT `stock_requests_received_by_foreign` FOREIGN KEY (`received_by`) REFERENCES `users` (`id`),
  CONSTRAINT `stock_requests_requested_by_foreign` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`),
  CONSTRAINT `stock_requests_requesting_facility_id_foreign` FOREIGN KEY (`requesting_facility_id`) REFERENCES `facilities` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


