INSERT INTO `access_groups` (`id`, `name`, `description`, `is_active`, `slug`, `created_at`, `updated_at`) VALUES
(85,	'All Healthcare Staff',	'General access group for all authenticated healthcare personnel. Includes basic clinical protocols and general health information.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(86,	'Clinical Leadership',	'Senior clinical staff and department heads with access to advanced protocols, quality improvement materials, and management resources.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(87,	'Program Coordinators',	'MNICH and diabetes program coordinators with access to program-specific materials, training resources, and coordination tools.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(88,	'New Healthcare Staff',	'Recently hired healthcare workers with access to orientation materials, basic clinical protocols, and foundational training content.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(89,	'Trainers & Mentors',	'Clinical trainers and mentors with access to educational resources, training materials, and instructional content for capacity building.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(90,	'Maternal Health Specialists',	'Obstetricians, midwives, and maternal health specialists with access to pregnancy care protocols, delivery procedures, and maternal health guidelines.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(91,	'Newborn Care Specialists',	'Neonatologists, pediatric nurses, and newborn care specialists with access to essential newborn care protocols and neonatal emergency procedures.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(92,	'Child Health Providers',	'Pediatricians, child health nurses, and providers specializing in infant and child health with access to IMCI protocols and child development resources.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(93,	'Diabetes Care Team',	'Endocrinologists, diabetes educators, and specialists focused on diabetes prevention, management, and patient education across all age groups.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(94,	'Midwives',	'Professional midwives with access to maternal care protocols, delivery procedures, family planning resources, and emergency obstetric care guidelines.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(95,	'Pediatric Nurses',	'Nurses specializing in pediatric care with access to child health protocols, growth monitoring procedures, and pediatric emergency care.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(96,	'Community Health Nurses',	'Public health and community nurses with access to community-based interventions, health education materials, and outreach resources.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(97,	'ICU/Critical Care Nurses',	'Intensive care nurses with access to critical care protocols, emergency procedures, and advanced life support resources.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(98,	'Community Health Workers',	'Community health volunteers and workers with access to community-level health promotion materials, basic care protocols, and referral guidelines.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(99,	'Traditional Birth Attendants',	'Trained traditional birth attendants with access to safe delivery practices, complication recognition, and referral protocols.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(100,	'Peer Educators',	'Community peer educators with access to health education materials, behavior change communication resources, and community mobilization tools.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(101,	'Laboratory Personnel',	'Laboratory technicians and staff with access to diagnostic procedures, testing protocols, quality control measures, and equipment maintenance.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(102,	'Pharmacy Staff',	'Pharmacists and pharmacy technicians with access to drug protocols, medication management, insulin storage guidelines, and pharmaceutical care.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(103,	'Nutritionists',	'Nutrition specialists with access to feeding guidelines, malnutrition management protocols, diabetes nutrition education, and growth monitoring resources.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(104,	'Data Management Staff',	'Health information officers and data managers with access to data collection tools, reporting formats, and quality assurance procedures.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(105,	'PMTCT Program Staff',	'Prevention of Mother-to-Child Transmission program staff with access to HIV testing protocols, antiretroviral therapy guidelines, and counseling resources.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(106,	'Immunization Team',	'EPI (Expanded Program on Immunization) staff with access to vaccination schedules, cold chain management, adverse event protocols, and coverage monitoring.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(107,	'Nutrition Program Staff',	'Nutrition program coordinators and staff with access to malnutrition screening tools, therapeutic feeding protocols, and nutrition education materials.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(108,	'Emergency Response Team',	'Emergency obstetric and newborn care teams with access to emergency protocols, resuscitation procedures, and critical care guidelines.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(109,	'Primary Health Centers',	'Staff at primary healthcare facilities with access to basic clinical protocols, referral guidelines, and community health interventions.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(110,	'District Hospitals',	'District hospital staff with access to comprehensive emergency obstetric care, neonatal intensive care, and specialized treatment protocols.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(111,	'Referral Hospitals',	'Tertiary care staff with access to advanced procedures, specialized protocols, and complex case management guidelines.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(112,	'Maternity Units',	'Maternity ward staff with access to delivery protocols, postpartum care procedures, and newborn care guidelines.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(113,	'Quality Improvement Teams',	'QI coordinators and teams with access to quality improvement methodologies, audit tools, performance indicators, and improvement strategies.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(114,	'Infection Prevention Teams',	'Infection prevention and control staff with access to hygiene protocols, antimicrobial stewardship guidelines, and outbreak response procedures.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(115,	'Research Teams',	'Research coordinators and staff with access to research protocols, data collection tools, ethics guidelines, and study procedures.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(116,	'Monitoring & Evaluation',	'M&E officers with access to indicator definitions, data collection tools, reporting templates, and evaluation frameworks.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(117,	'Health Records Officers',	'Medical records and health information management staff with access to documentation standards, filing procedures, and data management protocols.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(118,	'Supply Chain Management',	'Logistics and supply chain staff with access to commodity management protocols, inventory procedures, and distribution guidelines.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(119,	'Finance & Administration',	'Administrative staff with access to financial procedures, procurement guidelines, and administrative protocols.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(120,	'Medical Students',	'Medical students and interns with access to educational materials, clinical guidelines, and supervised learning resources.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(121,	'Nursing Students',	'Nursing students and trainees with access to basic clinical protocols, learning materials, and practical guidance.',	1,	'nursing-students',	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(122,	'Continuing Education Participants',	'Healthcare providers enrolled in continuing education programs with access to advanced training materials and certification resources.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(123,	'NGO Partners',	'Non-governmental organization staff working in MNICH and diabetes programs with access to relevant implementation guidelines and coordination materials.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(124,	'Development Partners',	'International development partners and donors with access to program documentation, progress reports, and strategic planning materials.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(125,	'Technical Advisors',	'External technical advisors and consultants with access to specialized protocols, evaluation tools, and technical guidance documents.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(126,	'Training Participants',	'Temporary group for healthcare providers participating in specific training programs with access to training materials and resources.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(127,	'Pilot Program Sites',	'Staff at facilities implementing pilot programs with access to pilot-specific protocols, implementation guides, and feedback tools.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(128,	'Compliance Officers',	'Regulatory and compliance staff with access to regulatory documents, audit materials, compliance checklists, and legal guidelines.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(129,	'Guest Lecturers',	'External trainers and guest speakers with limited access to presentation materials and relevant training resources.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(130,	'Contractors',	'External contractors and vendors with restricted access to relevant procedures and safety requirements for their specific work areas.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(131,	'Orientation Group',	'Temporary group for new staff during orientation period with access to onboarding materials and initial training resources.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25'),
(132,	'Project Team',	'Temporary access for specific project participants with access to project-related documentation and collaboration materials.',	1,	NULL,	'2025-08-02 16:17:25',	'2025-08-02 16:17:25');
