(3,	'Group Discussion',	'Facilitated open discussion among mentees on clinical topics or cases.',	NULL,	NULL,	NULL),
(4,	'Demonstration',	'Mentor-led demonstration of clinical or practical skills.',	NULL,	NULL,	NULL),
