(9,	'Role Play',	'Participants act out scenarios to practice skills.',	NULL,	NULL,	NULL),
(10,	'Video Demonstration',	'Sessions using pre-recorded videos to reinforce clinical skills.',	NULL,	NULL,	NULL),
(11,	'Drills',	'Rapid, repetitive practice of critical or emergency skills.',	NULL,	NULL,	NULL),
(12,	'Clinical Placement',	'Supervised practice in real healthcare settings.',	NULL,	NULL,	NULL),
(13,	'OSCE Assessment',	'Structured clinical assessment using checklists at skill stations.',	NULL,	NULL,	NULL),
(14,	'Mentorship Debrief',	'Structured reflection and feedback sessions after modules or cases.',	NULL,	NULL,	NULL),
(15,	'Use of Checklists',	'Use of structured checklists or scoring tools for assessment or feedback.',	NULL,	NULL,	NULL),
