INSERT INTO `resources` (`id`, `title`, `slug`, `excerpt`, `content`, `meta_description`, `featured_image`, `resource_type_id`, `category_id`, `author_id`, `status`, `visibility`, `is_featured`, `is_downloadable`, `download_count`, `view_count`, `like_count`, `dislike_count`, `published_at`, `file_path`, `file_size`, `file_type`, `external_url`, `duration`, `difficulty_level`, `prerequisites`, `learning_outcomes`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1,	'New Employee Orientation Guide',	'new-employee-orientation-guide',	'Comprehensive guide for new employees covering organizational structure, policies, and initial training requirements.',	'<h2>Welcome to Our Organization</h2><p>This comprehensive orientation guide will help you understand our organizational culture, values, and operational procedures.</p><h3>What You Will Learn</h3><ul><li>Organizational structure and reporting lines</li><li>Core values and mission statement</li><li>Basic policies and procedures</li><li>Safety requirements and protocols</li><li>Communication channels and tools</li></ul><h3>Getting Started</h3><p>Your first week will include meetings with your supervisor, HR orientation sessions, and initial training modules. Please review this material before your first day.</p>',	'Essential orientation guide for new employees covering organizational basics, policies, and initial training requirements.',	NULL,	38,	NULL,	1,	'published',	'authenticated',	1,	1,	40,	63,	2,	0,	'2025-07-23 16:18:48',	NULL,	NULL,	NULL,	NULL,	NULL,	'beginner',	'[\"None\"]',	'[\"Understand organizational structure\", \"Know basic policies and procedures\", \"Identify key contacts and resources\", \"Complete initial safety training\"]',	1,	'2025-08-02 16:18:48',	'2025-09-02 12:11:26',	NULL),
(2,	'Fire Safety and Emergency Procedures',	'fire-safety-emergency-procedures',	'Critical safety information including fire prevention, evacuation procedures, and emergency contact information.',	'<h2>Fire Safety Protocol</h2><p>Fire safety is everyone\'s responsibility. This guide covers prevention, response, and evacuation procedures.</p><h3>Prevention</h3><ul><li>Keep fire exits clear</li><li>Report electrical hazards immediately</li><li>Proper storage of flammable materials</li><li>Regular inspection of fire equipment</li></ul><h3>In Case of Fire</h3><ol><li>Sound the alarm</li><li>Evacuate immediately using nearest exit</li><li>Assist others if safe to do so</li><li>Proceed to assembly point</li><li>Do not use elevators</li></ol><h3>Emergency Contacts</h3><p>Fire Department: 999<br>Security: Ext. 2000<br>First Aid: Ext. 2100</p>',	'Essential fire safety and emergency procedures for all staff including prevention tips and evacuation protocols.',	NULL,	42,	NULL,	1,	'published',	'public',	1,	1,	37,	47,	5,	0,	'2025-07-28 16:18:48',	NULL,	NULL,	NULL,	NULL,	NULL,	'beginner',	'[\"None\"]',	'[\"Understand fire prevention measures\", \"Know evacuation procedures\", \"Identify emergency contacts\", \"Recognize fire safety equipment\"]',	2,	'2025-08-02 16:18:48',	'2025-12-01 17:00:38',	NULL),
(3,	'Effective Communication Skills Training',	'effective-communication-skills-training',	'Interactive training module on developing professional communication skills for workplace success.',	'<h2>Communication Excellence</h2><p>Effective communication is fundamental to professional success and positive workplace relationships.</p><h3>Key Communication Skills</h3><ul><li>Active listening techniques</li><li>Clear and concise verbal communication</li><li>Professional written communication</li><li>Non-verbal communication awareness</li><li>Conflict resolution strategies</li></ul><h3>Best Practices</h3><p>Always consider your audience, choose appropriate channels, provide clear context, and follow up when necessary.</p><h3>Interactive Exercises</h3><p>This module includes role-playing scenarios, communication assessments, and practical exercises to enhance your skills.</p>',	'Interactive communication skills training covering verbal, written, and non-verbal communication techniques.',	NULL,	44,	NULL,	1,	'published',	'authenticated',	0,	0,	23,	62,	11,	0,	'2025-07-30 16:18:48',	NULL,	NULL,	NULL,	NULL,	1800,	'intermediate',	'[\"Basic workplace experience\"]',	'[\"Apply active listening techniques\", \"Communicate clearly and professionally\", \"Handle difficult conversations\", \"Use appropriate communication channels\"]',	3,	'2025-08-02 16:18:48',	'2025-08-02 16:18:48',	NULL),
(4,	'Quality Improvement Fundamentals',	'quality-improvement-fundamentals',	'Introduction to quality improvement methodologies and tools for continuous organizational enhancement.',	'<h2>Quality Improvement Overview</h2><p>Quality improvement is a systematic approach to enhancing organizational processes and outcomes.</p><h3>Core Principles</h3><ul><li>Patient/customer focus</li><li>Data-driven decision making</li><li>Continuous improvement culture</li><li>Team-based approach</li><li>Leadership commitment</li></ul><h3>Common Tools</h3><ul><li>Plan-Do-Study-Act (PDSA) cycles</li><li>Root cause analysis</li><li>Process mapping</li><li>Statistical process control</li><li>Benchmarking</li></ul><h3>Implementation Steps</h3><p>Start with small, manageable projects and gradually build capacity for larger improvements.</p>',	'Fundamentals of quality improvement including methodologies, tools, and implementation strategies.',	NULL,	38,	NULL,	1,	'published',	'restricted',	0,	1,	46,	92,	11,	0,	'2025-08-01 16:18:48',	NULL,	NULL,	NULL,	NULL,	NULL,	'intermediate',	'[\"Basic understanding of organizational processes\"]',	'[\"Understand QI principles\", \"Apply basic QI tools\", \"Develop improvement plans\", \"Measure improvement outcomes\"]',	4,	'2025-08-02 16:18:48',	'2025-08-02 16:18:48',	NULL),
(5,	'Equipment Maintenance Checklist',	'equipment-maintenance-checklist',	'Standardized checklist for routine equipment maintenance and safety inspections.',	'<h2>Equipment Maintenance Protocol</h2><p>Regular maintenance ensures equipment reliability, safety, and longevity.</p><h3>Daily Checks</h3><ul><li>Visual inspection for damage</li><li>Check safety devices</li><li>Verify operational status</li><li>Clean and sanitize as required</li></ul><h3>Weekly Checks</h3><ul><li>Calibration verification</li><li>Moving parts lubrication</li><li>Filter replacement if needed</li><li>Performance testing</li></ul><h3>Monthly Checks</h3><ul><li>Comprehensive safety inspection</li><li>Preventive maintenance tasks</li><li>Documentation update</li><li>Service scheduling</li></ul><h3>Documentation</h3><p>All maintenance activities must be recorded with date, time, and technician signature.</p>',	'Comprehensive equipment maintenance checklist covering daily, weekly, and monthly inspection procedures.',	NULL,	43,	NULL,	1,	'published',	'authenticated',	0,	1,	48,	77,	17,	0,	'2025-08-02 16:18:48',	NULL,	NULL,	NULL,	NULL,	NULL,	'beginner',	'[\"Basic equipment familiarity\"]',	'[\"Perform routine inspections\", \"Complete maintenance documentation\", \"Identify maintenance issues\", \"Follow safety protocols\"]',	5,	'2025-08-02 16:18:48',	'2025-08-02 19:27:38',	NULL),
(6,	'Birthing Protocal',	'birthing-protocal',	'Guidance on how middle women can help',	'<p>For a period now we are unable to dse</p>',	NULL,	'resources/featured/01K1QG2Q8Y9SKETGTDFY0BDQ3A.PNG',	46,	66,	1,	'published',	'public',	0,	1,	0,	21,	0,	0,	'2025-08-03 05:11:36',	'resources/files/01K1QG2QA9FMWHZ4N49TAA9JHW.pdf',	NULL,	NULL,	'https://www.youtube.com/watch?v=hlgDFZEeI00&list=RDhlgDFZEeI00&start_radio=1',	10,	'intermediate',	'[]',	'[]',	0,	'2025-08-03 05:16:57',	'2025-11-30 23:47:09',	NULL),
